#!/usr/bin/env python3
"""Pulls facts out of the recorded logs into small, readable extracts.
Every extracted line is copied verbatim and tagged with its source file:line."""
import re, pathlib, subprocess, collections
R = pathlib.Path(__file__).resolve().parents[2]; E = R/'evidence'; T = E/'test-results'
def L(p): return (R/p).read_text(errors='replace').splitlines()
def grab(p, pats, ctx=0):
    out = []
    for i, l in enumerate(L(p), 1):
        if any(re.search(x, l) for x in pats): out.append(f'{p.split("/")[-1]}:{i:<4} {l.strip()}')
    return out
def write(p, title, body):
    (E/p).write_text(f'EXTRACT (generated by evidence/build/derive.py; source lines are verbatim)\n{title}\n' + '-'*72 + '\n' + '\n'.join(body) + '\n')
tr = 'evidence/test-results/'
m2, m4 = tr+'mac2-20261123-232344.txt', tr+'mac4-20261123-232352.txt'

write('01-lan/lan-reachability-recorded.txt', 'Pings and interface facts from the last passing runs, 23 Nov 2026 23:23',
  ['# from Mac 2'] + grab(m2, [r'interface en0', r'PASS  (ping|has a private|this Mac)']) + ['', '# from Mac 4'] + grab(m4, [r'interface en0', r'PASS  (ping|has a private|this Mac)']))
write('02-dns/dns-recorded.txt', 'Private DNS seen by Mac 4 as a client, 23 Nov 2026 23:23',
  grab(m4, [r'client uses Mac 1', r'backup DNS \(', r'PASS  dig', r'NXDOMAIN', r'google', r'macOS resolver', r'primary DNS', r'backup DNS Mac 4', r'TTL is']))
rows = ['X-Backend sequences through the edge, every run that reached it:', '']
for f in sorted(T.glob('mac[24]-*.txt')):
    for i, l in enumerate(f.read_text().splitlines(), 1):
        if 'X-Backend sequence' in l and '-' not in l.split(':')[1]: rows.append(f'{f.name}:{i:<4} {l.strip()}')
write('04-load-balancing/round-robin-recorded.txt', 'Load balancing on the team LAN, 23 Nov 2026', rows + [''] + grab(m2, ['round-robin']) + grab(m4, ['both backends serve']))
write('03-https/https-recorded.txt', 'HTTPS / TLS checks on the team LAN, 23 Nov 2026 23:23',
  ['# Mac 2 (the edge)'] + grab(m2, [r'cert', r'SAN', r'extendedKey', r'private key', r'TLS 1\.', r'HTTP/2']) + ['', '# Mac 4 (a client)'] + grab(m4, [r'curl https', r'subject:', r'issuer:', r'api\.team1.test also', r'HTTP/2', r'HTTP/1.1 also', r'TLS 1.2', r'X-Edge: mac2']))
write('06-caching/caching-recorded.txt', 'Caching through the HTTPS edge, 23 Nov 2026 23:23',
  grab(m4, [r'cache-control:', r'etag:', r'ETag', r'304', r'no-store', r'max-age']))
write('07-failures/failures-recorded.txt', 'Section 6.3 failure checks on the team LAN, 23 Nov 2026 23:23',
  ['# Mac 4 (client side)'] + grab(m4, [r'wrong DNS server', r'wrong IP', r'wrong port']) + ['', '# Mac 2 (private test edge on :18443, same config and certificate)'] + grab(m2, [r'Backend A dead', r'both backends dead']))
log = R/'logs/dns.log'
if log.exists():
    ll = log.read_text(errors='replace').splitlines()
    c = collections.Counter(l.split()[-1] for l in ll if ' query[' in l)
    write('08-backup-dns/backup-dns-log-excerpt.txt', 'Backup DNS on Mac 4: dnsmasq log of 23 Nov 2026. Only team1.test lines and totals are kept;\nother lines are the team\'s ordinary browsing lookups and are left out on purpose.',
      ['Queries answered, by client:'] + [f'  {n:5d}  from {ip}' + (' (Mac 1)' if ip.endswith('.224') else ' (Mac 4)') for ip, n in c.most_common()]
      + ['', 'Startup:'] + [l for l in ll[:30] if 'started, version' in l or 'nameserver' in l or 'locally-known' in l or 'Target IP' in l or 'BACKUP' in l]
      + ['', 'team1.test lines:'] + [f'dns.log:{i:<5} {l}' for i, l in enumerate(ll, 1) if 'team1.test' in l and ('query[' in l or 'config ' in l)])
write('08-backup-dns/backup-dns-recorded.txt', 'Both DNS servers answering the same record, 23 Nov 2026', grab(m4, ['backup DNS', 'primary DNS', 'TTL is']))
A, B = tr+'mac4-20261123-120313.txt', tr+'mac2-20261123-120236.txt'
write('11-service-isolation/isolation-recorded.txt', 'Firewall ON: client blocked, edge allowed, site still works (23 Nov 2026 12:02-12:03)',
  ['# Mac 2, 12:02:36 - the edge may connect'] + grab(B, [r'^TEAM 1', r'Mac 2 -> Backend']) + ['', '# Mac 4, 12:03:13 - a client may not, yet the site works through the edge'] + grab(A, [r'^TEAM 1', r'blocked', r'X-Backend sequence', r'both backends serve'])
  + ['', '# For contrast, Mac 4 at 12:42 and 23:23 with the firewall OFF'] + grab(tr+'mac4-20261123-124210.txt', ['Mac 3:3001 is reachable']) + grab(m4, ['Mac 3:3001 is reachable'])
  + ['', 'Two other files also print "blocked" but are NOT counted as proof:', '  mac4-20261123-113905  this Mac was not on the configured network, nothing was reachable', '  mac4-20261123-122033  Backend A was also unreachable from the edge (mac2-20261123-122006)'])
cut = 'evidence/12-edge-cutover/edge-cutover-121149.txt'
S = []
for i, l in enumerate(L(cut), 1):
    m = re.match(r'(\d\d:\d\d:\d\d)  (\S+)(?: \(([^)]*)\))?\s+(\S+)(?: \(([^)]*)\))?\s+(\S+)\s+(\S+)$', l)
    if m: S.append((i, m[1], m[2].split('.')[-1], m[4].split('.')[-1], m[6], m[7], l))
out, prev = ['Every line where something changed (of %d samples, about one every 2.2 s):' % len(S), ''], None
for i, t, d, c, e, st, l in S:
    if (d, c, e, st) != prev: out.append(f'{cut.split("/")[-1]}:{i:<4} {l}'); prev = (d, c, e, st)
win = [s for s in S if '12:11:49' <= s[1] <= '12:15:02']
out += ['', f'Cutover window 12:11:49-12:15:02: {len(win)} samples, {sum(s[5]=="200" for s in win)} returned 200, {sum(s[5]!="200" for s in win)} failed',
        f'Whole file: {len(S)} samples, {sum(s[5]=="200" for s in S)} returned 200, {sum(s[5]=="FAIL" for s in S)} failed (see 13-troubleshooting/incident-20261123.txt)']
write('12-edge-cutover/cutover-transitions.txt', 'Ext E cutover, 23 Nov 2026: state changes', out)
f1, f2 = [s for s in S if s[5] == 'FAIL'][0], [s for s in S if s[5] == 'FAIL' and s[1] < '12:30'][-1]
write('13-troubleshooting/incident-20261123.txt', f'A real outage recorded by three independent files on 23 Nov 2026 ({f1[1]} to {f2[1]})',
  ['# 1. Edge watcher on a client: last good, first bad, last bad, first good'] + [f'{cut.split("/")[-1]}:{s[0]:<4} {s[6]}' for k, s in enumerate(S) if s[0] in (f1[0]-1, f1[0], f2[0], f2[0]+1)]
  + ['', '# 2. Mac 2 test, 12:20:06'] + grab(tr+'mac2-20261123-122006.txt', [r'^TEAM 1', r'PASS  ping', r'FAIL  ']) 
  + ['', '# 3. Mac 4 test, 12:20:33'] + grab(tr+'mac4-20261123-122033.txt', [r'^TEAM 1', r'PASS  ping', r'primary DNS', r'backup DNS Mac 4', r'macOS resolver', r'HTTPS request failed', r'standby edge answers'])
  + ['', '# 4. Recovered: Mac 2, 12:39:28'] + grab(tr+'mac2-20261123-123928.txt', [r'^TEAM 1', r'nginx answers HTTPS', r'Mac 2 -> Backend', r'passed'])
  + ['', 'What the files do not say: why the primary DNS answered 10.128.139.55, or whether it was a deliberate drill.'])
print('derived ok')
